args.command:
cd /workspace && node -e '
const fs=require("fs");const p="/workspace/report.md";let s=fs.readFileSync(p,"utf8");
const rep=(a,b)=>{if(!s.includes(a))throw new Error("missing "+a.slice(0,50));s=s.split(a).join(b);};
rep("* **Stale-snapshot evidence:** the owner then `PATCH`ed the object",
"* **Stale-snapshot evidence:** on a separate object (`7e96f1a2-3be1-4f78-a05a-65bc2bf45ee5`) warmed and read by anonymous first (`200`), the owner then `PATCH`ed the object");
rep("Deletion by a non-owner returned `404` for every class tested (orders, invoices, tenant-notes, bulletins, catalog,\nprivate-reports, cached-reports, login-reports, forbidden-reports, expiring-reports).",
"Deletion by a non-owner returned `404` for every class tested (orders, invoices, tenant-notes, bulletins, catalog,\nprivate-reports, cached-reports, login-reports, stale-reports, forbidden-reports, expiring-reports); non-owner deletion\nof `echo-reports` was not exercised.");
rep("scoped classes (`invoices`, `tenant-notes`, `private-reports` before the anonymous-path bug, `cached-reports`,\n`expiring-reports`), so no role-based bypass was observed.",
"scoped classes (`invoices`, `tenant-notes`, `private-reports`, `cached-reports`, `expiring-reports` all returned `404` to\nadmin), so no role-based bypass was observed. The `admin` account did receive the same leaked bodies where Findings 1–7\napply, consistent with those leaks not depending on the caller's role.");
fs.writeFileSync(p,s);console.log("patched");'
grep -n "non-owner deletion" -B2 -A2 /workspace/report.md

cd /workspace && cat > /tmp/patch.js <<'JS'
const fs=require("fs");const p="/workspace/report.md";let s=fs.readFileSync(p,"utf8");
const rep=(a,b)=>{if(!s.includes(a))throw new Error("missing "+a.slice(0,50));s=s.split(a).join(b);};
rep("* **Stale-snapshot evidence:** the owner then `PATCH`ed the object",
"* **Stale-snapshot evidence:** on a separate object (`7e96f1a2-3be1-4f78-a05a-65bc2bf45ee5`), warmed and anonymously read first (`200`), the owner then `PATCH`ed the object");
rep("Deletion by a non-owner returned `404` for every class tested (orders, invoices, tenant-notes, bulletins, catalog,\nprivate-reports, cached-reports, login-reports, forbidden-reports, expiring-reports).",
"Deletion by a non-owner returned `404` for every class tested (orders, invoices, tenant-notes, bulletins, catalog,\nprivate-reports, cached-reports, login-reports, stale-reports, forbidden-reports, expiring-reports); non-owner deletion\nof `echo-reports` was not exercised.");
rep("scoped classes (`invoices`, `tenant-notes`, `private-reports` before the anonymous-path bug, `cached-reports`,\n`expiring-reports`), so no role-based bypass was observed.",
"scoped classes (`invoices`, `tenant-notes`, `private-reports`, `cached-reports`, `expiring-reports` all returned `404` to\nadmin), so no role-based bypass was observed. Where Findings 1-7 apply, `admin` received the same leaked bodies as the\nother callers, consistent with those leaks not depending on the caller's role.");
fs.writeFileSync(p,s);console.log("patched");
JS
node /tmp/patch.js && grep -n "Stale-snapshot" -A3 report.md && echo --- && grep -n "non-owner returned" -A3 report.md && echo --- && grep -n "role-based bypass" -B3 -A2 report.md

cd /workspace && cat > /tmp/patch2.js <<'JS'
const fs=require("fs");const p="/workspace/report.md";let s=fs.readFileSync(p,"utf8");
const a="* **Stale-snapshot evidence:** on a separate object (`7e96f1a2-3be1-4f78-a05a-65bc2bf45ee5`), warmed and anonymously read first (`200`), the owner then `PATCH`ed the object to `{\"note\":\"stale-warm-PATCHED\"}` (`204`); bob's next\n  `GET` returned the **pre-PATCH** value `{\"note\":\"stale-warm\"}`, showing the second subject was served the cached\n  authorization/response snapshot rather than a freshly authorized read.";
const b="* **Stale-snapshot evidence:** on a separate object (`7e96f1a2-3be1-4f78-a05a-65bc2bf45ee5`), the owner's read made\n  anonymous `GET` return `200 {\"note\":\"stale-warm\"}`; the owner then `PATCH`ed it to `{\"note\":\"stale-warm-PATCHED\"}` (`204`),\n  after which bob's `GET` still returned the **pre-PATCH** value `{\"note\":\"stale-warm\"}`. The second subject was therefore\n  served the cached authorization/response snapshot, not a freshly authorized read.";
if(!s.includes(a)) throw new Error("not found");
fs.writeFileSync(p,s.split(a).join(b));console.log("ok");
JS
node /tmp/patch2.js; sed -n '100,145p' /workspace/report.md

cd /workspace && cat > /tmp/p3.js <<'JS'
const fs=require("fs");const p="/workspace/report.md";let s=fs.readFileSync(p,"utf8");
s=s.replace("Raw evidence (request/response pairs) is in `/workspace/evidence.log` plus the supplementary runs summarized below.",
"Raw evidence (request/response pairs) is in `/workspace/out/evidence.log`, plus the supplementary runs summarized below.");
fs.writeFileSync(p,s);console.log("ok");
JS
node /tmp/p3.js; grep -n "Raw evidence" report.md
